refentry.refsect1:
  &reftitle.examples;

   Exemple avec Yaf_Controller_Abstract::forward


<?php
class IndexController extends Yaf_Controller_Abstract
{
    public function indexAction() {
        $logined = $_SESSION["login"];
        if (!$logined) {
            $this->forward("login", array("from" => "Index")); // transfère vers l'action login
            return false; // ceci est important, cela termine le flux courant
                          // et indique à Yaf de ne pas effectuer le rendu automatique
        }

        // autres traitements
    }

    public function loginAction() {
        echo "login, redirigé depuis l'action ", $this->_request->getParam("from");
    }
}
?>


   &example.outputs.similar;


   login, redirigé depuis l'action Index
